import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { recipeAPI } from '../api';
import useAuth from '../hooks/useAuth';
import RecipeCard from '../components/RecipeCard';
import './Profile.css';

const Profile = () => {
  const { user } = useAuth();
  const [userRecipes, setUserRecipes] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('recipes');

  if (!user) return <div>Loading user...</div>;

  useEffect(() => {
    const loadUserRecipes = async () => {
      try {
        setLoading(true);
        // Fetch all recipes and filter by owner
        const { data } = await recipeAPI.getAllRecipes({});
        const userOwnedRecipes = data.recipes.filter(
          (r) => r.owner?._id === user?.id
        );

        setUserRecipes(userOwnedRecipes);

        // Get user data with favorites
        const { user: userData } = await (await fetch(`/api/auth/me`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        })).json();
        setFavorites(userData?.favoriteRecipes || []);
      } catch (error) {
        console.error('Error loading user data:', error);
      } finally {
        setLoading(false);
      }
    };

    loadUserRecipes();
  }, [user.id]);

  if (loading) return <div className="loading">Loading profile...</div>;

  return (
    <div className="profile-page">
      <div className="profile-header">
        <div className="profile-avatar">{user.username[0].toUpperCase()}</div>
        <div className="profile-info">
          <h1>{user?.username}</h1>
          <p>{user?.email}</p>
        </div>
      </div>

      <div className="profile-tabs">
        <button
          className={`tab-btn ${activeTab === 'recipes' ? 'active' : ''}`}
          onClick={() => setActiveTab('recipes')}
        >
          My Recipes ({userRecipes.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'favorites' ? 'active' : ''}`}
          onClick={() => setActiveTab('favorites')}
        >
          Favorites ({favorites.length})
        </button>
      </div>

      <div className="profile-content">
        {activeTab === 'recipes' && (
          <div>
            <Link to="/create" className="create-link">Create New Recipe</Link>
            {userRecipes.length > 0 ? (
              <div className="recipes-grid">
                {userRecipes.map((recipe) => (
                  <RecipeCard key={recipe._id} recipe={recipe} />
                ))}
              </div>
            ) : (
              <p className="empty-state">You haven't created any recipes yet. Create one now!</p>
            )}
          </div>
        )}

        {activeTab === 'favorites' && (
          <div>
            {favorites.length > 0 ? (
              <div className="recipes-grid">
                {favorites.map((recipe) => (
                  <RecipeCard key={recipe._id} recipe={recipe} />
                ))}
              </div>
            ) : (
              <p className="empty-state">You haven't favorited any recipes yet.</p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default Profile;
